import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { normalizeStrategyParams } from "./strategy-library.ts";

// Data migration 0059: run A definitions of the 11 QuantConnect idea ports, linked from the 0057
// library rows (card vertex-qc-ports). Generated by scripts/research/qc-port-definitions.ts.
const read = (path: string) =>
  readFileSync(new URL(path, import.meta.url), "utf8");
const migration = read("../../migrations/0059_qc_port_definitions.sql");
const rollback = read("../../rollback/0059_qc_port_definitions.down.sql");
const catalog = read("../../migrations/0057_strategy_catalog_qc_ports.sql");
const journal = JSON.parse(read("../../migrations/meta/_journal.json")) as {
  entries: Array<{ idx: number; tag: string }>;
};

const ROW =
  /\('(qc-def-(qc-[a-z0-9-]+)-r1)', '(qc-[a-z0-9-]+)', 1, '((?:[^']|'')+)', '((?:[^']|'')+)'::jsonb, '([0-9a-f]{64})', '((?:[^']|'')+)', 'migration:0059'\)/gu;
const UPDATE =
  /UPDATE "strategies" SET "params" = '((?:[^']|'')+)'::jsonb WHERE "id" = '(strategy-seed-qc-[a-z0-9-]+)' AND "params" = '\[\]'::jsonb AND EXISTS \(SELECT 1 FROM "strategy_definition_revisions" r WHERE r."id" = '(qc-def-qc-[a-z0-9-]+-r1)' AND r."sha256" = '([0-9a-f]{64})' AND r."created_by" = 'migration:0059'\);/gu;
const rows = [...migration.matchAll(ROW)];
const updates = [...migration.matchAll(UPDATE)];
const unquote = (text: string | undefined) =>
  (text ?? "").replaceAll("''", "'");

const canonical = (value: unknown): string => {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (typeof value === "object" && value !== null) {
    return `{${Object.keys(value)
      .sort()
      .map(
        (key) =>
          `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`
      )
      .join(",")}}`;
  }
  return JSON.stringify(value);
};

describe("0059_qc_port_definitions", () => {
  it("inserts revision 1 of each of the 11 catalog ideas, never overwriting", () => {
    expect(rows).toHaveLength(11);
    const ideas = rows.map((row) => row[2]);
    expect(ideas).toEqual([...ideas].sort());
    for (const [
      ,
      id,
      idea,
      definitionId,
      name,
      definition,
      sha256,
      note,
    ] of rows) {
      expect(id).toBe(`qc-def-${idea}-r1`);
      expect(definitionId).toBe(idea);
      expect(catalog).toContain(`'strategy-seed-${idea}', '${idea}'`);
      const text = unquote(definition);
      const parsed = JSON.parse(text) as Record<string, unknown>;
      expect(canonical(parsed)).toBe(text);
      expect(createHash("sha256").update(text).digest("hex")).toBe(sha256);
      expect(parsed["name"]).toBe(unquote(name));
      expect(unquote(name).length).toBeLessThanOrEqual(120);
      expect(unquote(note)).toMatch(
        new RegExp(
          `^Research run A of ${idea}: from \\d{4}-\\d{2}-\\d{2}, capital 100000, data to \\d{4}-\\d{2}-\\d{2} \\(research_studies ${idea}\\)$`,
          "u"
        )
      );
    }
    expect(migration).toContain("ON CONFLICT DO NOTHING;");
  });

  it("links each library row only while its params are empty, leaving updated_at alone", () => {
    expect(updates.map((update) => update[2])).toEqual(
      rows.map((row) => `strategy-seed-${row[2]}`)
    );
    for (const [index, [, params]] of updates.entries()) {
      const [, , idea, , , , sha256, note] = rows[index] ?? [];
      const start = /from (\d{4}-\d{2}-\d{2})/u.exec(note ?? "")?.[1];
      const parsed = normalizeStrategyParams(JSON.parse(unquote(params)));
      expect(
        parsed.map((param) => [param.name, param.type, param.default])
      ).toEqual([
        ["definitionId", "choice", idea],
        ["definitionSha256", "choice", sha256],
        ["runFrom", "choice", start],
        ["initialCapital", "choice", "100000"],
      ]);
      expect(parsed.every((param) => param.options?.length === 1)).toBe(true);
    }
    expect(migration).not.toMatch(/updated_at/u);
  });

  it("links only when the matching 0059 revision exists, with literal backslashes", () => {
    expect(updates).toHaveLength(11);
    for (const [index, update] of updates.entries()) {
      const row = rows[index];
      expect([update[3], update[4]]).toEqual([row?.[1], row?.[6]]);
    }
    expect(migration.split("\n--> statement-breakpoint\n")[0]).toContain(
      "SET LOCAL standard_conforming_strings = on;"
    );
    expect(rollback).toContain("SET LOCAL standard_conforming_strings = on;");
  });

  it("is journaled at index 59", () => {
    expect(journal.entries[59]).toMatchObject({
      idx: 59,
      tag: "0059_qc_port_definitions",
    });
  });

  return it("rolls back only the 0059 rows and params, refusing on later edits", () => {
    for (const [, id, idea] of rows) {
      expect(rollback).toContain(`'${id}'`);
      expect(rollback).toContain(`'strategy-seed-${idea}'`);
    }
    for (const [, params] of updates) expect(rollback).toContain(`'${params}'`);
    expect(rollback).toContain(
      `r."id" NOT IN (${rows.map((row) => `'${row[1]}'`).join(", ")}) OR r."revision" <> 1 OR r."created_by" <> 'migration:0059'`
    );
    expect(rollback).toContain(
      "qc-port definitions have later revisions or rows by other authors; refusing rollback"
    );
    expect(rollback).toContain(
      "qc-port library params were changed after 0059; refusing rollback"
    );
    expect(rollback).toContain(`AND s."params" = l.params;`);
    expect(rollback).toContain(
      `DELETE FROM "public"."strategy_definition_revisions" WHERE "created_by" = 'migration:0059' AND "revision" = 1 AND ("id", "definition_id", "sha256") IN (${rows.map((row) => `('${row[1]}', '${row[3]}', '${row[6]}')`).join(", ")});`
    );
    for (const table of [
      "strategy_presets",
      "strategy_specs",
      "backtest_results",
      "backtest_runs",
      "optimization_runs",
      "deployment_requests",
      "autopilot_candidates",
    ]) {
      expect(rollback).toMatch(
        new RegExp(
          `"public"\\."${table}" [a-z] WHERE [a-z]\\."strategy_id" = l\\.id`,
          "u"
        )
      );
    }
    expect(rollback).toContain(
      "qc-port seed strategies are referenced by runs, results or specs; refusing rollback"
    );
    expect(rollback).not.toMatch(/CASCADE|TRUNCATE|updated_at/iu);
  });
});
